"""Author the reviewed mentoring seed; does not touch existing lesson modules."""
from pathlib import Path
import json
from html import escape
ROOT=Path(__file__).resolve().parent
def p(text): return '<p>'+text+'</p>'
def link(url,label): return '<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>'
fifa='https://www.fifatrainingcentre.com/en/environment/practical-example/coaching-development/the-coach-educator/student-coach-mentoring-promoting-reflection.php'
raabe='https://cris.fau.de/publications/225323479/'
haugan='https://www.mdpi.com/2075-4663/9/8/116'
safe='https://www.aysovolunteers.org/policy-safe-haven-cvpa/'
report='https://www.ussoccer.com/safeguarding/report-a-concern'
match='https://learn.englandfootball.com/articles-and-resources/coaching/resources/2024/How-coaches-can-manage-matchday'
experience='https://learn.englandfootball.com/articles-and-resources/coaching/resources/2022/How-to-create-a-great-matchday-experience'
rows=[
('research','What the research tells us',3,'Explain why we observe, reflect, try and check again.',[
('Start with the child','Mentoring helps an adult coach make one useful change and notice what it does for the children. We use observation, reflection, specific feedback and another attempt. Intent over outcome is our coaching value: recognise a purposeful decision even when execution is unsuccessful. It is not an empirical feedback-effect claim.'),
('Findings and limits',link(raabe,'Raabe and colleagues (2019)')+' reviewed interventions with PE teachers and youth-sport coaches. Their review suggests support can change adult behaviour; it does not validate our Hub or a particular visit length. '+link(haugan,'Haugan and colleagues (2021)')+' studied a Norwegian coach-mentoring programme. Coach and athlete perceptions did not consistently agree. This setting and self-report evidence cannot establish effects for grassroots U6–U8 children. Feeling more confident is useful information, but does not demonstrate better practice or player experience.'),
('Our proposed application','Agree one coach behaviour, observe what happens, let the coach interpret it, and test an achievable change. Ask what would count as an unhelpful result. If it does not help, adapt the idea rather than blame the coach. Psychological safety here means making it possible to ask for help and discuss mistakes without humiliation; safeguarding duties still apply.'),
('Optional mentor guidance',link(fifa,'FIFA’s student-coach example')+' illustrates a pre-brief, agreed observation and reflective feedback in a licence-assessment setting. We adapt the conversation for development, separate from formal assessment. A successful playing career does not replace preparation in listening, questioning, feedback and boundaries. Practise describing an event before offering advice.')],
'Choose one coaching behaviour and describe what the children might experience differently.',[
('A coach feels more confident after the visit. What can we conclude?',['Mentoring has improved the children’s learning.','Confidence changed; we still need to observe practice and player experience.','Confidence has no value.'],1,'Confidence and observed practice are different outcomes; ask what the children experienced.'),
('A former professional player volunteers as a mentor. What preparation is needed?',['Playing experience replaces preparation.','Only a longer list of drills.','Prepare listening, feedback, supervision and hand-back boundaries.'],2,'Playing knowledge may help, but does not establish mentoring skill.'),
('The first experiment does not help. What next?',['Review observations with the coach and adapt one thing.','Record success because the visit happened.','Insist on the same approach indefinitely.'],0,'An unhelpful attempt is information for the next decision, not proof the coach failed.')]),
('methods','Choosing a mentoring method',4,'Choose support that fits the coach and return ownership.',[
('Four practical options','Ask and reflect: help the coach compare options. Observe and feed back: describe specific events rather than personality. Demonstrate and hand back: show one brief agreed example, then the coach tries. Plan or coach together: share a defined task and agree when the coach resumes it.'),
('Make a simple agreement','Use “Watch me”, “Show me” or “Work with me”. Agree the purpose and hand-back point. A beginner who cannot picture a game may need a demonstration; questions alone can frustrate them. An experienced coach may want to test alternatives rather than receive a running commentary.'),
('Illustrative volunteer example: engagement','A volunteer notices long waits. Agree to shorten the explanation and run two smaller games. Observe waiting in the same short window before and afterwards. Hand the organisation back to the volunteer. A busier session is not, by itself, proof of retained learning; ask about involvement and revisit the setup.'),
('Optional mentor guidance','Ask permission before changing methods. “Would a short example help?” Explain what you will show, keep it brief and invite the coach’s own attempt immediately. Do not take over the entire practice by default.')],
'Agree Watch me, Show me or Work with me, including when ownership returns.',[
('A beginner cannot picture the activity. What fits?',['Keep asking increasingly abstract questions.','Demonstrate briefly, then let the coach try immediately.','Take the whole session.'],1,'A short model can help a beginner if ownership returns quickly.'),
('An experienced coach has two possible adaptations. What fits?',['Ask what each might change and test one.','Choose for them without discussion.','Avoid observing because they are experienced.'],0,'Support the coach’s judgement and compare observations.'),
('The mentor proposes leading the whole practice. What must happen?',['Assume mentoring transfers all responsibility.','Remove the coach from all decisions.','Agree a useful purpose, responsibilities and a hand-back point.'],2,'Shared coaching needs an explicit agreement; mentoring should build ownership.')]),
('before','Before the visit',3,'Confirm the arrangement, one focus and supervision.',[
('Reuse the request','Check the current season/team, age group, practice or game, time and location. Check who is currently assigned and whether they have accepted. A submitted form is requested, not booked. Cover for an absent coach is a separate staffing responsibility with eligibility checks.'),
('Agree one focus','Ask: what would make coaching easier? Choose one observable adult behaviour and one thing the children might do differently. Agree Watch me, Show me or Work with me; when may the mentor intervene and when should feedback wait? Record the accepted arrangement before marking confirmed.'),
('Responsibilities remain explicit','Name who retains team supervision, emergency responsibility and substitutions. Maintain never-alone and existing supervision requirements throughout demonstrations and adult debriefs. Mentoring does not grant team-area eligibility or replace required screening, qualifications or safeguarding training.'),
('Optional mentor guidance','If time, venue, focus or mentor changes, reconfirm rather than assume. Do not import old spreadsheet rows as current appointments. Use the printable pre-visit agreement to check the details together.')],
'Agree one behaviour, one child-experience sign and a confirmed arrangement.',[
('A coach submits a request. Is the visit confirmed?',['Yes, the form is a booking.','Yes, once the date has passed.','No; it needs an agreed arrangement and accepted mentor assignment.'],2,'A request records interest; confirmation needs agreement.'),
('The request asks someone to cover an absent coach. What next?',['Resolve staffing and eligibility separately from mentoring.','Assume every mentor may lead the team.','Mark the visit delivered.'],0,'Cover needs its own responsibility and supervision checks.'),
('The coach lists five concerns. How should you prepare?',['Promise to resolve all five in one visit.','Choose one main behaviour together and a sign to observe.','Use the mentor’s usual topic regardless.'],1,'A shared, specific focus makes observation and follow-up manageable.')]),
('practice','During practice',4,'Observe facts, support briefly and hand back.',[
('Observe first','Unless a demonstration was agreed, let the coach lead. Capture two factual examples: what the adult did and what the children did next, without identifying children. “The explanation lasted through two restarts” is more useful than “poor communicator”. Keep observation windows short enough to maintain your assigned duties.'),
('Make one useful adjustment','Offer a brief question or demonstration, or adjust space, numbers or challenge. Return ownership. Avoid long queues and explanations. Never use exclusion, exercise or humiliation as punishment for mistakes. Act immediately on safety concerns through the applicable procedure; do not wait for a debrief.'),
('Illustrative volunteer example: support and passing','Start with a manageable 4v1, add a second defender when appropriate, then revisit support in a wider game. The 4v1 progression comes from the supplied mentoring proposal; it is not a newly verified Hub resource. The existing 4v2 Rondo is tagged U12/U14, so adapt cautiously rather than prescribe it to beginners. Ask about another passing option instead of calling every pass. Observe whether teammates offer choices and the coach allows decision time.'),
('Existing resources and boundaries','Use Hide &amp; Seek for protecting and finding support, or a small 3v3 game adapted to the children. Hide &amp; Seek and 4v2 Rondo are verified Hub activities; the particular progressive sequence is an illustrative application. Practice constraints and bonus scoring do not alter official match rules. Review old conditions before reuse; do not revive punitive removal rules.')],
'Record two factual examples, one short intervention and the hand-back.',[
('Players are waiting in a long queue. What might help?',['A longer explanation to the whole group.','Consider smaller parallel games and observe involvement.','Punish the waiting players with exercise.'],1,'Change the organisation and check the effect rather than blame the children.'),
('The mentor disagrees with a minor coaching choice. What should they do?',['Shout an alternative to the players.','Take control without asking.','Use the agreed quiet prompt or wait for private feedback.'],2,'Support ownership and avoid competing instructions.'),
('An unsafe setup becomes apparent. What next?',['Act immediately through the safety procedure.','Wait until the debrief to protect ownership.','Treat it only as a quiz topic.'],0,'Immediate safety takes priority over the normal observation agreement.')]),
('games','Supporting coaches during games',5,'Use the matchday card while the coach leads.',[
('Before kick-off','Connect the match focus to practice. Agree what to observe, mentor location, quiet-prompt method and supervision duties. Choose whole-match support or a clearly timed window. Check local team-area eligibility, playing-time/substitution rules and emergency arrangements. A mentor without approved team-area access observes from a permitted location.'),
('During play','The coach leads and the mentor observes. Offer a brief quiet prompt only as agreed. Do not issue competing player instructions, argue with spectators or officials, or enter the field without authorisation. Safety overrides waiting for a debrief. Support an agreed duty only if it does not compromise supervision.'),
('Half-time','Water and recovery first. The coach leads. Share one useful observation and one achievable cue, with player input where appropriate. Recognise a purposeful attempt. Do not turn a short break into a second adult lecture or delay a restart.'),
('After the final whistle','Finish supervision and safe handover before an adult debrief, or agree a later conversation. No public critique. Capture one learning observation and one next-practice action. The score provides context; it is not the measure of mentoring success.'),
('Illustrative staff-coach example','Agree to observe tone, body language and intervention timing under pressure. After conceding, use the agreed quiet prompt. Recognise a brave decision even if possession was lost. Later compare one helpful intervention with a moment where silence would have helped. Keep this developmental conversation separate from formal performance assessment.'),
('Practitioner guidance',link(match,'England Football: managing matchday')+' and '+link(experience,'creating a great matchday experience')+' provide practical guidance on player involvement, observation and adult behaviour. These are practitioner resources, not trials establishing programme effectiveness. Use the four-section blank matchday card in My mentoring → Field cards.')],
'Agree a matchday observation window and one calm prompt before kick-off.',[
('The team concedes. What should the mentor do?',['Call different instructions over the coach.','Argue with the referee.','Observe the pattern and offer only the agreed calm prompt.'],2,'Keep one clear adult lead; the score does not change the agreement.'),
('Half-time is short. What takes priority?',['Water, recovery and one useful message led by the coach.','A full tactical lecture from both adults.','Public criticism of the most recent mistake.'],0,'Recovery and one achievable cue protect a manageable player experience.'),
('The mentor wants to change substitutions. What next?',['Make the changes independently.','Discuss with the responsible coach and follow local playing-time rules.','Use a practice bonus rule to change match eligibility.'],1,'Mentoring does not transfer team responsibility or override competition rules.')]),
('after','After the visit and into the next session',3,'Agree one next action and check what happened.',[
('Let the coach speak first','Ask what worked, what the children did and what the coach would change. Add one specific strength and one useful factual observation. Keep feedback private and about behaviour, not personality. The coach chooses one achievable next action.'),
('Close the loop','Link one relevant activity or lesson and agree a follow-up owner/date. Ask whether the action was tried and what happened. “Not yet” and “It did not help” are valid responses. Decide whether to retry, adapt or close with a reason; do not manufacture success.'),
('Protect supervision','A debrief waits until supervision and safe handover are complete. If time is short, agree a later adult conversation. A short practice visit and whole-match support require different time allocations; agree capacity instead of promising overlapping coverage.'),
('Optional mentor guidance','At the next visit, revisit the previous action before introducing a new topic. Compare the same adult behaviour and a relevant sign of player experience. One positive observation is a starting point for enquiry, not proof of lasting learning.')],
'Agree one action, one resource, an owner and a next check.',[
('You noticed five possible improvements. What next?',['Set five compulsory actions.','Agree one useful action with the coach.','Avoid mentioning a strength.'],1,'Prioritising makes the next attempt manageable.'),
('Children still need supervision after the game. When should you debrief?',['Immediately, leaving them to manage themselves.','Publicly while parents wait.','After safe handover, or at an agreed later time.'],2,'Do not abandon supervision for an adult conversation.'),
('A follow-up is due. What should you ask first?',['Was the previous action tried, and what happened?','Which new topic can replace the old one?','Did the team win?'],0,'Check the agreed experiment before adding another demand.')]),
('records','Recording support and following through',3,'Keep useful adult records and respect their limits.',[
('Four different records','A request describes a need and proposed arrangement. Linked visits preserve each occasion separately. An action records the next attempt; a follow-up records what happened or why it closed. Mentor assignment does not establish attendance. Lesson completion, delivered support and improved practice are separate things.'),
('Who sees the notes','These are shared adult development records linked to your account, not anonymous notes. The coach, currently assigned mentor and authorised programme administrator can see them. Ask for a correction through the same record or coordinator; changes retain author/time and field-change metadata. Do not promise absolute confidentiality or use this as formal assessment.'),
('Keep children out of the log','Do not enter children’s names, identifying details, health information, private family information, safeguarding allegations or identifiable child footage. Record adult behaviours and non-identifying observations only. Safeguarding concerns go immediately through the approved restricted reporting procedure, never the mentoring queue. See '+link(safe,'AYSO Safe Haven')+' and '+link(report,'U.S. Soccer reporting guidance')+'; the local reporting procedure must be confirmed before pilot collection.'),
('Follow through honestly','Use requested, arranging, confirmed, delivered, follow-up due, closed, postponed or cancelled. Confirmation needs the coach’s agreement and current mentor’s acceptance. Delivery requires a coach/mentor confirmation the visit happened. A past date is not attendance. Delivery must preserve outstanding follow-ups. Close only when actions have results or closure reasons. Retention and deletion, including backups, need an approved organisational policy; no fixed period is assumed.')],
'Check one shared adult record for accuracy and agree the next follow-up.',[
('A mentor is assigned and the proposed date is past. Was the visit delivered?',['Yes, automatically.','No; the coach or mentor must confirm attendance.','Only if the coach completed a quiz.'],1,'Assignment, elapsed time and lesson completion are not evidence of delivery.'),
('A draft note contains a child’s name and medical details. What next?',['Keep it because only staff can see it.','Copy it to the request topic.','Remove it from routine development notes and use the proper restricted process if required.'],2,'Mentoring records should describe adult practice without child-identifying information.'),
('A safeguarding disclosure arises. Where does it go?',['Immediately through the approved reporting procedure.','Into the next ordinary mentoring follow-up.','Into a public lesson reflection.'],0,'Do not delay reporting or put allegations in the mentoring queue.')])]
c=json.loads((ROOT/'catalogue.json').read_text(encoding='utf-8'))
c['version']='0.3.1'
ids=[]
for slug,title,minutes,outcome,sections,action,questions in rows:
 id='mentoring-'+slug; ids.append(id)
 body={'id':id,'title':title,'minutes':minutes,'summary':outcome,'mediaIds':[],
 'sections':[{'heading':'Your outcome','html':p(outcome)+p('Estimated reading time; check at your own pace. This is developmental support, separate from qualifications and formal assessment.')}]+[{'heading':h,'html':p(t)} for h,t in sections],
 'quiz':[{'id':id+'-'+str(i+1),'prompt':q,'options':opts,'correct':answer,'explanation':why} for i,(q,opts,answer,why) in enumerate(questions)],'takeaway':action,'sourceRefs':[]}
 (ROOT/'content/lessons'/f'{id}.json').write_text(json.dumps(body,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 c['lessons']=[x for x in c['lessons'] if x['id']!=id]+[{k:body[k] for k in ['id','title','minutes','summary','mediaIds']}]
for group,item in [('categories',{'id':'coach-mentoring','title':'Coach Mentoring','summary':'One useful change, observed with the children and revisited.','lessonIds':ids}),('courses',{'id':'coach-mentoring','title':'Coach Mentoring — optional support','summary':'Seven short lessons for coaches, volunteers and mentors. Separate from foundation completion.','categoryIds':['coach-mentoring']}),('learningPathways',{'id':'mentoring-support','title':'Optional mentoring support','summary':'Shared support for staff coaches and volunteers; existing foundations stay unchanged.','tracks':['coach','volunteer'],'courseIds':['coach-mentoring']})]:
 c[group]=[x for x in c[group] if x['id']!=item['id']]+[item]
(ROOT/'catalogue.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Authored seven lessons and 21 scenario questions; existing foundation records unchanged.')
